                                    onClick: () => {
                                      patch({
                                        secTarget: pPeer.key,
                                        secMode: pRun ? 'steer' : 'followup',
                                        notice: bi('已在下方锁定 @', 'Locked target @') + (pPeer.name || pPeer.key),
                                      })
                                      focusSecInput()
                                    },
